query SearchPrints($query: String!, $limit: Int!) {
  searchPrints2(query: $query, printType: print, limit: $limit, ordering: best_match) {
    items {
      id
      name
      slug
      summary
      description
      created
      firstPublish
      datePublished
      modified
      likesCount
      downloadCount
      ratingAvg
      filesCount
      price
      user { publicUsername }
      image { filePath }
      license { name }
      category { name }
      tags { name }
    }
  }
}
